from collections import deque
from typing import List

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Build initial graph: 0->1, 1->2, ..., (n-2)->(n-1)
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        result = []

        for u, v in queries:
            # Add the new road from u to v
            graph[u].append(v)

            # Find shortest path from 0 to n-1 using BFS
            visited = [False] * n
            queue = deque([(0, 0)])  # (city, distance)
            visited[0] = True

            while queue:
                city, dist = queue.popleft()
                if city == n - 1:
                    result.append(dist)
                    break

                for neighbor in graph[city]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append((neighbor, dist + 1))
            else:
                # This should not happen as there's always a path
                result.append(n - 1)

        return result

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final (row, col) position to linear index
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store count of balls of each color for each player
        player_color_count = {}

        # Initialize for each player
        for i in range(n):
            player_color_count[i] = {}

        # Process each pick
        for player, color in pick:
            if color in player_color_count[player]:
                player_color_count[player][color] += 1
            else:
                player_color_count[player][color] = 1

        # Count how many players win
        winners = 0

        # Check each player
        for player in range(n):
            # Player i wins if they have at least (i+1) balls of the same color
            max_balls_of_same_color = max(player_color_count[player].values()) if player_color_count[player] else 0
            if max_balls_of_same_color >= player + 1:
                winners += 1

        return winners

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def calculate_flips(axis):
            """
            Calculate minimum flips needed when axis is 'row' (0) or 'col' (1)
            """
            total_flips = 0

            if axis == 0:  # Rows
                for i in range(m):
                    # For each row, check symmetric pairs
                    left = 0
                    right = n - 1
                    while left < right:
                        if grid[i][left] != grid[i][right]:
                            total_flips += 1
                        left += 1
                        right -= 1
            else:  # Columns
                for j in range(n):
                    # For each column, check symmetric pairs
                    top = 0
                    bottom = m - 1
                    while top < bottom:
                        if grid[top][j] != grid[bottom][j]:
                            total_flips += 1
                        top += 1
                        bottom -= 1

            return total_flips

        # Calculate flips for rows and columns
        row_flips = calculate_flips(0)
        col_flips = calculate_flips(1)

        return min(row_flips, col_flips)
